import{_ as a,o as p,c as n,ag as e}from"./chunks/framework.lghGfHnE.js";const t="/ai-docs/assets/img_01.Dm3PRmni.webp",i="/ai-docs/assets/img_02.BVuSlCU8.webp",o="/ai-docs/assets/img_03.BBUt7wBR.webp",c="/ai-docs/assets/video_01_wxv_4621617201211621378.CPAxC5Lr.mp4",r="/ai-docs/assets/video_02_wxv_4621617842369069057.bCvVpleQ.mp4",l="/ai-docs/assets/img_04.5aJFuhha.png",d="/ai-docs/assets/video_03_wxv_4621619556414078978.Da3YXVuw.mp4",m="/ai-docs/assets/img_05.tG-wwoff.webp",_="/ai-docs/assets/video_04_wxv_4621620250487128066.Drf_jJyG.mp4",b="/ai-docs/assets/img_06.DrNO0WdG.webp",g="/ai-docs/assets/video_05_wxv_4621621582078377990.C0e5756f.mp4",u="/ai-docs/assets/img_07.BH5fP_e3.png",h="/ai-docs/assets/img_08.BfLsJXGE.png",w=JSON.parse('{"title":"RabbitMQ：Agent 中异步处理的标配方案","description":"","frontmatter":{},"headers":[],"relativePath":"前端转AI Agent/37-RabbitMQ：Agent 中异步处理的标配方案/index.md","filePath":"前端转AI Agent/37-RabbitMQ：Agent 中异步处理的标配方案/index.md"}'),v={name:"前端转AI Agent/37-RabbitMQ：Agent 中异步处理的标配方案/index.md"};function k(A,s,Q,q,x,C){return p(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="rabbitmq-agent-中异步处理的标配方案" tabindex="-1">RabbitMQ：Agent 中异步处理的标配方案 <a class="header-anchor" href="#rabbitmq-agent-中异步处理的标配方案" aria-label="Permalink to &quot;RabbitMQ：Agent 中异步处理的标配方案&quot;">​</a></h1><p>RAG 流程里，pdf、docx、pptx 等各类文档上传后会解析为 markdown 格式</p><p>然后会分片存入向量数据库（比如 Milvus），会存入 ElasticSearch 做全文检索。</p><p>那解析的接口做向量化、ES 存储，需要同步等它们完成么？</p><p>很明显没必要，这俩完全可以异步来做。</p><p>后端如果想做异步处理，一般都是用消息队列 MQ，比如 RabbitMQ</p><p><img src="'+t+'" alt="img_01.webp"></p><p>解析完文档得到 Markdown 后，往 MQ 发一条消息</p><p>两个消费者收到消息后，分别做不同的处理。</p><p>RabbitMQ 的架构是这样的：</p><p><img src="'+i+`" alt="img_02.webp"></p><p>Producer 和 Consumer 分别是生产者和消费者。</p><p>Connection 是客户端与 RabbitMQ 服务之间的 TCP 物理连接。</p><p>我们不会每次收发消息都新建独立 Connection，因为 TCP 连接创建开销较高；</p><p>所以在一条 Connection 内部划分多条逻辑通道，也就是 Channel。</p><p>生产者和消费者都是绑定到具体的 channel 来收发消息。</p><p>Queue 队列，是真正存放消息的容器，消息最终存在队列中等待消费者处理。</p><p>整套承载消息接收、路由、转发的 RabbitMQ 服务实例，统称为 Broker。</p><p>至于 Exchange，这个是把消息放到不同的队列里用的，叫做交换机。</p><p>它负责把我们发的消息按照规则放入不同的 Queue 里</p><p>Exchange 主要有 4 种：</p><ul><li>fanout：把消息放到这个交换机的所有 Queue</li><li>direct：把消息放到交换机的指定 key 的队列</li><li>topic：把消息放到交换机的指定 key 的队列，支持模糊匹配</li><li>headers：把消息放到交换机的满足某些 header 的队列</li></ul><p>我们分别来试一下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir rabbitmq-test</span></span>
<span class="line"><span>cd rabbitmq-test</span></span>
<span class="line"><span>npm init -y</span></span></code></pre></div><p><img src="`+o+`" alt="img_03.webp"></p><p>先创建 docker-compose.yml 把它跑起来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>services:</span></span>
<span class="line"><span>  rabbitmq:</span></span>
<span class="line"><span>    image: rabbitmq:3.13-management</span></span>
<span class="line"><span>    container_name: rabbitmq</span></span>
<span class="line"><span>    restart: always</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;5672:5672&quot;</span></span>
<span class="line"><span>      - &quot;15672:15672&quot;</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      RABBITMQ_DEFAULT_USER: admin</span></span>
<span class="line"><span>      RABBITMQ_DEFAULT_PASS: Admin@123456</span></span>
<span class="line"><span>      RABBITMQ_DEFAULT_VHOST: /</span></span>
<span class="line"><span>    volumes:</span></span>
<span class="line"><span>      - ./rabbitmq_data:/var/lib/rabbitmq</span></span></code></pre></div><p><video src="`+c+'" controls></video></p><p>然后我们代码连上</p><p>nodejs 链接 rabbitmq 是用 amqplib 这个包：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm install amqplib</span></span></code></pre></div><p>先跑一下 direct 类型交换机（代码从仓库复制）：</p><p><video src="'+r+'" controls></video></p><p>这种交换机，会根据消息的 routing key 把消息传给精确匹配 routing key 的队列</p><p><img src="'+l+'" alt="img_04.png"></p><p>然后是 fanout 类型的交换机：</p><p><video src="'+d+'" controls></video></p><p>这种交换机，不看 routing key，会把收到的消息广播到所有绑定的队列</p><p><img src="'+m+'" alt="img_05.webp"></p><p>然后是 topic 类型的交换机</p><p><video src="'+_+'" controls></video></p><p>这个类型的交换机是根据通配符类匹配</p><ul><li>是匹配任意一个段</li></ul><h1 id="是匹配0-到任意个段" tabindex="-1">是匹配0 到任意个段 <a class="header-anchor" href="#是匹配0-到任意个段" aria-label="Permalink to &quot;是匹配0 到任意个段&quot;">​</a></h1><p><img src="'+b+'" alt="img_06.webp"></p><p>最后来看一下 headers 类型</p><p><video src="'+g+'" controls></video></p><p>headers 类型的交换机不再看 routing key，而是根据 headers 来匹配</p><p><img src="'+u+'" alt="img_07.png"></p><p>这样，4 种交换机类型我们就都过了一遍。</p><p><img src="'+h+'" alt="img_08.png"></p><blockquote><p>代码上传了课程仓库： <a href="https://github.com/QuarkGluonPlasma/ai-agent-course-code" target="_blank" rel="noreferrer">https://github.com/QuarkGluonPlasma/ai-agent-course-code</a></p></blockquote><p><strong>总结</strong></p><p>这节我们学了 RabbitMQ。</p><p>后端的异步任务基本都是通过 mq 来做。</p><p>生产者往队列里存入消息，消费者取出来处理，整个过程是异步的。</p><p>我们学了 RabbitMQ 的架构，包括 Connection、Channel、Exchange、Queue、Producer、Consumer 这些概念</p><p>以及 4 种交换机类型：direct、topic、fanout、headers</p><p>后面 Agent 应用涉及到异步的场景，都会用 RabbitMQ 来实现。</p>',59)])])}const R=a(v,[["render",k]]);export{w as __pageData,R as default};
